#include <vector>
#include <stack>

using namespace std;

class Solution {
public:
    long long subArrayRanges(vector<int>& nums) {
        return sumOfMax(nums) - sumOfMin(nums);
    }

    long long sumOfMax(vector<int>& nums) {
        long long res = 0;
        stack<int> s;
        int n = nums.size();
        for (int i = 0; i <= n; ++i) {
            while (!s.empty() && (i == n || nums[s.top()] < nums[i])) {
                int mid = s.top(); s.pop();
                int left = s.empty() ? -1 : s.top();
                res += (long long)nums[mid] * (i - mid) * (mid - left);
            }
            s.push(i);
        }
        return res;
    }

    long long sumOfMin(vector<int>& nums) {
        long long res = 0;
        stack<int> s;
        int n = nums.size();
        for (int i = 0; i <= n; ++i) {
            while (!s.empty() && (i == n || nums[s.top()] > nums[i])) {
                int mid = s.top(); s.pop();
                int left = s.empty() ? -1 : s.top();
                res += (long long)nums[mid] * (i - mid) * (mid - left);
            }
            s.push(i);
        }
        return res;
    }
};
